module axixclk #(
		parameter integer C_S_AXI_ID_WIDTH	= 2,
		parameter integer C_S_AXI_DATA_WIDTH	= 32,
		parameter integer C_S_AXI_ADDR_WIDTH	= 6,
		parameter [0:0]	OPT_WRITE_ONLY = 1'b0,
		parameter [0:0]	OPT_READ_ONLY = 1'b0,
		parameter	XCLOCK_FFS = 2,
		parameter	LGFIFO = 5
	) (
		input	wire				S_AXI_ACLK,
		input	wire				S_AXI_ARESETN,
		input	wire [C_S_AXI_ID_WIDTH-1 : 0]	S_AXI_AWID,
		input	wire [C_S_AXI_ADDR_WIDTH-1 : 0]	S_AXI_AWADDR,
		input	wire [7 : 0]			S_AXI_AWLEN,
		input	wire [2 : 0]			S_AXI_AWSIZE,
		input	wire [1 : 0]			S_AXI_AWBURST,
		input	wire				S_AXI_AWLOCK,
		input	wire [3 : 0]			S_AXI_AWCACHE,
		input	wire [2 : 0]			S_AXI_AWPROT,
		input	wire [3 : 0]			S_AXI_AWQOS,
		input	wire				S_AXI_AWVALID,
		output	wire				S_AXI_AWREADY,
		input	wire [C_S_AXI_DATA_WIDTH-1 : 0]	S_AXI_WDATA,
		input	wire [(C_S_AXI_DATA_WIDTH/8)-1 : 0] S_AXI_WSTRB,
		input	wire				S_AXI_WLAST,
		input	wire				S_AXI_WVALID,
		output	wire				S_AXI_WREADY,
		output	wire [C_S_AXI_ID_WIDTH-1 : 0]	S_AXI_BID,
		output	wire [1 : 0]			S_AXI_BRESP,
		output	wire				S_AXI_BVALID,
		input	wire				S_AXI_BREADY,
		input	wire [C_S_AXI_ID_WIDTH-1 : 0]	S_AXI_ARID,
		input	wire [C_S_AXI_ADDR_WIDTH-1 : 0]	S_AXI_ARADDR,
		input	wire [7 : 0]			S_AXI_ARLEN,
		input	wire [2 : 0]			S_AXI_ARSIZE,
		input	wire [1 : 0]			S_AXI_ARBURST,
		input	wire				S_AXI_ARLOCK,
		input	wire [3 : 0]			S_AXI_ARCACHE,
		input	wire [2 : 0]			S_AXI_ARPROT,
		input	wire [3 : 0]			S_AXI_ARQOS,
		input	wire				S_AXI_ARVALID,
		output	wire				S_AXI_ARREADY,
		output	wire [C_S_AXI_ID_WIDTH-1 : 0]	S_AXI_RID,
		output	wire [C_S_AXI_DATA_WIDTH-1 : 0]	S_AXI_RDATA,
		output	wire [1 : 0]			S_AXI_RRESP,
		output	wire				S_AXI_RLAST,
		output	wire				S_AXI_RVALID,
		input	wire				S_AXI_RREADY,
		input	wire				M_AXI_ACLK,
		output	wire				M_AXI_ARESETN,
		output	wire [C_S_AXI_ID_WIDTH-1 : 0]	M_AXI_AWID,
		output	wire [C_S_AXI_ADDR_WIDTH-1 : 0]	M_AXI_AWADDR,
		output	wire [7 : 0]			M_AXI_AWLEN,
		output	wire [2 : 0]			M_AXI_AWSIZE,
		output	wire [1 : 0]			M_AXI_AWBURST,
		output	wire				M_AXI_AWLOCK,
		output	wire [3 : 0]			M_AXI_AWCACHE,
		output	wire [2 : 0]			M_AXI_AWPROT,
		output	wire [3 : 0]			M_AXI_AWQOS,
		output	wire				M_AXI_AWVALID,
		input	wire				M_AXI_AWREADY,
		output	wire [C_S_AXI_DATA_WIDTH-1 : 0]	M_AXI_WDATA,
		output	wire [(C_S_AXI_DATA_WIDTH/8)-1 : 0] M_AXI_WSTRB,
		output	wire				M_AXI_WLAST,
		output	wire				M_AXI_WVALID,
		input	wire				M_AXI_WREADY,
		input	wire [C_S_AXI_ID_WIDTH-1 : 0]	M_AXI_BID,
		input	wire [1 : 0]			M_AXI_BRESP,
		input	wire				M_AXI_BVALID,
		output	wire				M_AXI_BREADY,
		output	wire [C_S_AXI_ID_WIDTH-1 : 0]	M_AXI_ARID,
		output	wire [C_S_AXI_ADDR_WIDTH-1 : 0]	M_AXI_ARADDR,
		output	wire [7 : 0]			M_AXI_ARLEN,
		output	wire [2 : 0]			M_AXI_ARSIZE,
		output	wire [1 : 0]			M_AXI_ARBURST,
		output	wire				M_AXI_ARLOCK,
		output	wire [3 : 0]			M_AXI_ARCACHE,
		output	wire [2 : 0]			M_AXI_ARPROT,
		output	wire [3 : 0]			M_AXI_ARQOS,
		output	wire				M_AXI_ARVALID,
		input	wire				M_AXI_ARREADY,
		input	wire [C_S_AXI_ID_WIDTH-1 : 0]	M_AXI_RID,
		input	wire [C_S_AXI_DATA_WIDTH-1 : 0]	M_AXI_RDATA,
		input	wire [1 : 0]			M_AXI_RRESP,
		input	wire				M_AXI_RLAST,
		input	wire				M_AXI_RVALID,
		output	wire				M_AXI_RREADY
	);

	// Internal signals
	reg [C_S_AXI_ID_WIDTH-1 : 0]	s_awid_reg, m_awid_reg;
	reg [C_S_AXI_ADDR_WIDTH-1 : 0]	s_awaddr_reg, m_awaddr_reg;
	reg [7 : 0]				s_awlen_reg, m_awlen_reg;
	reg [2 : 0]				s_awsize_reg, m_awsize_reg;
	reg [1 : 0]				s_awburst_reg, m_awburst_reg;
	reg					s_awlock_reg, m_awlock_reg;
	reg [3 : 0]				s_awcache_reg, m_awcache_reg;
	reg [2 : 0]				s_awprot_reg, m_awprot_reg;
	reg [3 : 0]				s_awqos_reg, m_awqos_reg;
	reg					s_awvalid_reg, m_awvalid_reg;
	reg					s_awready_reg, m_awready_reg;

	reg [C_S_AXI_DATA_WIDTH-1 : 0]	s_wdata_reg, m_wdata_reg;
	reg [(C_S_AXI_DATA_WIDTH/8)-1 : 0]	s_wstrb_reg, m_wstrb_reg;
	reg					s_wlast_reg, m_wlast_reg;
	reg					s_wvalid_reg, m_wvalid_reg;
	reg					s_wready_reg, m_wready_reg;

	reg [C_S_AXI_ID_WIDTH-1 : 0]	s_bid_reg, m_bid_reg;
	reg [1 : 0]				s_bresp_reg, m_bresp_reg;
	reg					s_bvalid_reg, m_bvalid_reg;
	reg					s_bready_reg, m_bready_reg;

	reg [C_S_AXI_ID_WIDTH-1 : 0]	s_arid_reg, m_arid_reg;
	reg [C_S_AXI_ADDR_WIDTH-1 : 0]	s_araddr_reg, m_araddr_reg;
	reg [7 : 0]				s_arlen_reg, m_arlen_reg;
	reg [2 : 0]				s_arsize_reg, m_arsize_reg;
	reg [1 : 0]				s_arburst_reg, m_arburst_reg;
	reg					s_arlock_reg, m_arlock_reg;
	reg [3 : 0]				s_arcache_reg, m_arcache_reg;
	reg [2 : 0]				s_arprot_reg, m_arprot_reg;
	reg [3 : 0]				s_arqos_reg, m_arqos_reg;
	reg					s_arvalid_reg, m_arvalid_reg;
	reg					s_arready_reg, m_arready_reg;

	reg [C_S_AXI_ID_WIDTH-1 : 0]	s_rid_reg, m_rid_reg;
	reg [C_S_AXI_DATA_WIDTH-1 : 0]	s_rdata_reg, m_rdata_reg;
	reg [1 : 0]				s_rresp_reg, m_rresp_reg;
	reg					s_rlast_reg, m_rlast_reg;
	reg					s_rvalid_reg, m_rvalid_reg;
	reg					s_rready_reg, m_rready_reg;

	// FIFOs for write address channel
	wire [C_S_AXI_ID_WIDTH + C_S_AXI_ADDR_WIDTH + 15 : 0] awfifo_din, awfifo_dout;
	wire awfifo_full, awfifo_empty, awfifo_valid;
	fifo #(.WIDTH(C_S_AXI_ID_WIDTH + C_S_AXI_ADDR_WIDTH + 15), .DEPTH(1<<LGFIFO))
		awfifo (
			.clk(S_AXI_ACLK),
			.rst(!S_AXI_ARESETN),
			.din({s_awid_reg, s_awaddr_reg, s_awlen_reg, s_awsize_reg, s_awburst_reg, s_awlock_reg, s_awcache_reg, s_awprot_reg, s_awqos_reg}),
			.wr_en(s_awvalid_reg & s_awready_reg),
			.rd_en(m_awvalid_reg & m_awready_reg),
			.dout(awfifo_dout),
			.full(awfifo_full),
			.empty(awfifo_empty),
			.valid(awfifo_valid)
		);

	// FIFOs for write data channel
	wire [C_S_AXI_DATA_WIDTH + (C_S_AXI_DATA_WIDTH/8) + 1 : 0] wfifo_din, wfifo_dout;
	wire wfifo_full, wfifo_empty, wfifo_valid;
	fifo #(.WIDTH(C_S_AXI_DATA_WIDTH + (C_S_AXI_DATA_WIDTH/8) + 1), .DEPTH(1<<LGFIFO))
		wfifo (
			.clk(S_AXI_ACLK),
			.rst(!S_AXI_ARESETN),
			.din({s_wdata_reg, s_wstrb_reg, s_wlast_reg}),
			.wr_en(s_wvalid_reg & s_wready_reg),
			.rd_en(m_wvalid_reg & m_wready_reg),
			.dout(wfifo_dout),
			.full(wfifo_full),
			.empty(wfifo_empty),
			.valid(wfifo_valid)
		);

	// FIFOs for write response channel
	wire [C_S_AXI_ID_WIDTH + 1 : 0] bfifo_din, bfifo_dout;
	wire bfifo_full, bfifo_empty, bfifo_valid;
	fifo #(.WIDTH(C_S_AXI_ID_WIDTH + 1), .DEPTH(1<<LGFIFO))
		bfifo (
			.clk(M_AXI_ACLK),
			.rst(!S_AXI_ARESETN),
			.din({m_bid_reg, m_bresp_reg}),
			.wr_en(m_bvalid_reg & m_bready_reg),
			.rd_en(s_bvalid_reg & s_bready_reg),
			.dout(bfifo_dout),
			.full(bfifo_full),
			.empty(bfifo_empty),
			.valid(bfifo_valid)
		);

	// FIFOs for read address channel
	wire [C_S_AXI_ID_WIDTH + C_S_AXI_ADDR_WIDTH + 15 : 0] arfifo_din, arfifo_dout;
	wire arfifo_full, arfifo_empty, arfifo_valid;
	fifo #(.WIDTH(C_S_AXI_ID_WIDTH + C_S_AXI_ADDR_WIDTH + 15), .DEPTH(1<<LGFIFO))
		arfifo (
			.clk(S_AXI_ACLK),
			.rst(!S_AXI_ARESETN),
			.din({s_arid_reg, s_araddr_reg, s_arlen_reg, s_arsize_reg, s_arburst_reg, s_arlock_reg, s_arcache_reg, s_arprot_reg, s_arqos_reg}),
			.wr_en(s_arvalid_reg & s_arready_reg),
			.rd_en(m_arvalid_reg & m_arready_reg),
			.dout(arfifo_dout),
			.full(arfifo_full),
			.empty(arfifo_empty),
			.valid(arfifo_valid)
		);

	// FIFOs for read data channel
	wire [C_S_AXI_ID_WIDTH + C_S_AXI_DATA_WIDTH + 2 : 0] rfifo_din, rfifo_dout;
	wire rfifo_full, rfifo_empty, rfifo_valid;
	fifo #(.WIDTH(C_S_AXI_ID_WIDTH + C_S_AXI_DATA_WIDTH + 2), .DEPTH(1<<LGFIFO))
		rfifo (
			.clk(M_AXI_ACLK),
			.rst(!S_AXI_ARESETN),
			.din({m_rid_reg, m_rdata_reg, m_rresp_reg, m_rlast_reg}),
			.wr_en(m_rvalid_reg & m_rready_reg),
			.rd_en(s_rvalid_reg & s_rready_reg),
			.dout(rfifo_dout),
			.full(rfifo_full),
			.empty(rfifo_empty),
			.valid(rfifo_valid)
		);

	// Write Address Channel
	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN) begin
			s_awvalid_reg <= 1'b0;
		end else begin
			if (s_awvalid_reg & s_awready_reg) begin
				s_awvalid_reg <= 1'b0;
			end else if (S_AXI_AWVALID & !awfifo_full) begin
				s_awid_reg <= S_AXI_AWID;
				s_awaddr_reg <= S_AXI_AWADDR;
				s_awlen_reg <= S_AXI_AWLEN;
				s_awsize_reg <= S_AXI_AWSIZE;
				s_awburst_reg <= S_AXI_AWBURST;
				s_awlock_reg <= S_AXI_AWLOCK;
				s_awcache_reg <= S_AXI_AWCACHE;
				s_awprot_reg <= S_AXI_AWPROT;
				s_awqos_reg <= S_AXI_AWQOS;
				s_awvalid_reg <= 1'b1;
			end
		end
	end

	always @(posedge M_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN) begin
			m_awvalid_reg <= 1'b0;
		end else begin
			if (m_awvalid_reg & m_awready_reg) begin
				m_awvalid_reg <= 1'b0;
			end else if (awfifo_valid) begin
				{m_awid_reg, m_awaddr_reg, m_awlen_reg, m_awsize_reg, m_awburst_reg, m_awlock_reg, m_awcache_reg, m_awprot_reg, m_awqos_reg} <= awfifo_dout;
				m_awvalid_reg <= 1'b1;
			end
		end
	end

	assign S_AXI_AWREADY = !s_awvalid_reg & !awfifo_full;
	assign M_AXI_AWVALID = m_awvalid_reg;

	// Write Data Channel
	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN) begin
			s_wvalid_reg <= 1'b0;
		end else begin
			if (s_wvalid_reg & s_wready_reg) begin
				s_wvalid_reg <= 1'b0;
			end else if (S_AXI_WVALID & !wfifo_full) begin
				s_wdata_reg <= S_AXI_WDATA;
				s_wstrb_reg <= S_AXI_WSTRB;
				s_wlast_reg <= S_AXI_WLAST;
				s_wvalid_reg <= 1'b1;
			end
		end
	end

	always @(posedge M_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN) begin
			m_wvalid_reg <= 1'b0;
		end else begin
			if (m_wvalid_reg & m_wready_reg) begin
				m_wvalid_reg <= 1'b0;
			end else if (wfifo_valid) begin
				{m_wdata_reg, m_wstrb_reg, m_wlast_reg} <= wfifo_dout;
				m_wvalid_reg <= 1'b1;
			end
		end
	end

	assign S_AXI_WREADY = !s_wvalid_reg & !wfifo_full;
	assign M_AXI_WVALID = m_wvalid_reg;

	// Write Response Channel
	always @(posedge M_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN) begin
			m_bvalid_reg <= 1'b0;
		end else begin
			if (m_bvalid_reg & m_bready_reg) begin
				m_bvalid_reg <= 1'b0;
			end else if (M_AXI_BVALID & !bfifo_full) begin
				m_bid_reg <= M_AXI_BID;
				m_bresp_reg <= M_AXI_BRESP;
				m_bvalid_reg <= 1'b1;
			end
		end
	end

	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN) begin
			s_bvalid_reg <= 1'b0;
		end else begin
			if (s_bvalid_reg & s_bready_reg) begin
				s_bvalid_reg <= 1'b0;
			end else if (bfifo_valid) begin
				{s_bid_reg, s_bresp_reg} <= bfifo_dout;
				s_bvalid_reg <= 1'b1;
			end
		end
	end

	assign M_AXI_BREADY = !m_bvalid_reg & !bfifo_full;
	assign S_AXI_BVALID = s_bvalid_reg;

	// Read Address Channel
	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN) begin
			s_arvalid_reg <= 1'b0;
		end else begin
			if (s_arvalid_reg & s_arready_reg) begin
				s_arvalid_reg <= 1'b0;
			end else if (S_AXI_ARVALID & !arfifo_full) begin
				s_arid_reg <= S_AXI_ARID;
				s_araddr_reg <= S_AXI_ARADDR;
				s_arlen_reg <= S_AXI_ARLEN;
				s_arsize_reg <= S_AXI_ARSIZE;
				s_arburst_reg <= S_AXI_ARBURST;
				s_arlock_reg <= S_AXI_ARLOCK;
				s_arcache_reg <= S_AXI_ARCACHE;
				s_arprot_reg <= S_AXI_ARPROT;
				s_arqos_reg <= S_AXI_ARQOS;
				s_arvalid_reg <= 1'b1;
			end
		end
	end

	always @(posedge M_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN) begin
			m_arvalid_reg <= 1'b0;
		end else begin
			if (m_arvalid_reg & m_arready_reg) begin
				m_arvalid_reg <= 1'b0;
			end else if (arfifo_valid) begin
				{m_arid_reg, m_araddr_reg, m_arlen_reg, m_arsize_reg, m_arburst_reg, m_arlock_reg, m_arcache_reg, m_arprot_reg, m_arqos_reg} <= arfifo_dout;
				m_arvalid_reg <= 1'b1;
			end
		end
	end

	assign S_AXI_ARREADY = !s_arvalid_reg & !arfifo_full;
	assign M_AXI_ARVALID = m_arvalid_reg;

	// Read Data Channel
	always @(posedge M_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN) begin
			m_rvalid_reg <= 1'b0;
		end else begin
			if (m_rvalid_reg & m_rready_reg) begin
				m_rvalid_reg <= 1'b0;
			end else if (M_AXI_RVALID & !rfifo_full) begin
				m_rid_reg <= M_AXI_RID;
				m_rdata_reg <= M_AXI_RDATA;
				m_rresp_reg <= M_AXI_RRESP;
				m_rlast_reg <= M_AXI_RLAST;
				m_rvalid_reg <= 1'b1;
			end
		end
	end

	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN) begin
			s_rvalid_reg <= 1'b0;
		end else begin
			if (s_rvalid_reg & s_rready_reg) begin
				s_rvalid_reg <= 1'b0;
			end else if (rfifo_valid) begin
				{s_rid_reg, s_rdata_reg, s_rresp_reg, s_rlast_reg} <= rfifo_dout;
				s_rvalid_reg <= 1'b1;
			end
		end
	end

	assign M_AXI_RREADY = !m_rvalid_reg & !rfifo_full;
	assign S_AXI_RVALID = s_rvalid_reg;

	// Output assignments
	assign S_AXI_BID = s_bid_reg;
	assign S_AXI_BRESP = s_bresp_reg;
	assign S_AXI_RID = s_rid_reg;
	assign S_AXI_RDATA = s_rdata_reg;
	assign S_AXI_RRESP = s_rresp_reg;
	assign S_AXI_RLAST = s_rlast_reg;

	assign M_AXI_AWID = m_awid_reg;
	assign M_AXI_AWADDR = m_awaddr_reg;
	assign M_AXI_AWLEN = m_awlen_reg;
	assign M_AXI_AWSIZE = m_awsize_reg;
	assign M_AXI_AWBURST = m_awburst_reg;
	assign M_AXI_AWLOCK = m_awlock_reg;
	assign M_AXI_AWCACHE = m_awcache_reg;
	assign M_AXI_AWPROT = m_awprot_reg;
	assign M_AXI_AWQOS = m_awqos_reg;

	assign M_AXI_WDATA = m_wdata_reg;
	assign M_AXI_WSTRB = m_wstrb_reg;
	assign M_AXI_WLAST = m_wlast_reg;

	assign M_AXI_ARID = m_arid_reg;
	assign M_AXI_ARADDR = m_araddr_reg;
	assign M_AXI_ARLEN = m_arlen_reg;
	assign M_AXI_ARSIZE = m_arsize_reg;
	assign M_AXI_ARBURST = m_arburst_reg;
	assign M_AXI_ARLOCK = m_arlock_reg;
	assign M_AXI_ARCACHE = m_arcache_reg;
	assign M_AXI_ARPROT = m_arprot_reg;
	assign M_AXI_ARQOS = m_arqos_reg;

	assign M_AXI_ARESETN = S_AXI_ARESETN;

endmodule

module fifo #(
		parameter WIDTH = 8,
		parameter DEPTH = 16
	) (
		input	wire				clk,
		input	wire				rst,
		input	wire [WIDTH-1 : 0]		din,
		input	wire				wr_en,
		input	wire				rd_en,
		output	wire [WIDTH-1 : 0]		dout,
		output	wire				full,
		output	wire				empty,
		output	wire				valid
	);

	reg [$clog2(DEPTH)-1 : 0]	wr_ptr, rd_ptr;
	reg [$clog2(DEPTH)-1 : 0]	count;
	reg [WIDTH-1 : 0]		mem [0 : DEPTH-1];

	always @(posedge clk or posedge rst) begin
		if (rst) begin
			wr_ptr <= 0;
			rd_ptr <= 0;
			count <= 0;
		end else begin
			if (wr_en & !full) begin
				mem[wr_ptr] <= din;
				wr_ptr <= wr_ptr + 1;
				count <= count + 1;
			end
			if (rd_en & !empty) begin
				rd_ptr <= rd_ptr + 1;
				count <= count - 1;
			end
		end
	end

	assign dout = mem[rd_ptr];
	assign full = (count == DEPTH);
	assign empty = (count == 0);
	assign valid = !empty;

endmodule
